Running command: # Check if the system gnutls has the bug by looking at the source
# First, let's try to compile and run a test
cat > /tmp/test_poc.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <gnutls/gnutls.h>
#include <gnutls/pkcs12.h>
#include <gnutls/x509.h>

int main(int argc, char **argv) {
    FILE *f;
    unsigned char buf[64*1024];
    size_t size;
    gnutls_datum_t raw;
    gnutls_pkcs12_t p12;
    gnutls_x509_privkey_t key;
    gnutls_x509_crt_t *chain = NULL;
    gnutls_x509_crt_t *extras = NULL;
    gnutls_x509_crl_t crl = NULL;
    unsigned int chain_len = 0, extras_len = 0;
    int ret;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <p12_file>\n", argv[0]);
        return 1;
    }

    f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    size = fread(buf, 1, sizeof(buf), f);
    fclose(f);
    if (size <= 0) return 1;

    raw.data = buf;
    raw.size = size;

    gnutls_global_init();

    ret = gnutls_pkcs12_init(&p12);
    if (ret < 0) { fprintf(stderr, "init failed\n"); return 1; }

    ret = gnutls_pkcs12_import(p12, &raw, GNUTLS_X509_FMT_DER, 0);
    if (ret < 0) { fprintf(stderr, "import failed: %s\n", gnutls_strerror(ret)); goto cleanup; }

    gnutls_pkcs12_verify_mac(p12, "1234");

    ret = gnutls_pkcs12_simple_parse(p12, "1234", &key, &chain, &chain_len, &extras, &extras_len, &crl, 0);
    fprintf(stderr, "parse returned: %d (%s)\n", ret, gnutls_strerror(ret));
    if (ret >= 0) {
        gnutls_x509_privkey_deinit(key);
        if (crl) gnutls_x509_crl_deinit(crl);
        if (extras_len > 0) {
            unsigned int i;
            for (i=0;i<extras_len;i++) gnutls_x509_crt_deinit(extras[i]);
            gnutls_free(extras);
        }
        if (chain_len > 0) {
            unsigned int i;
            for (i=0;i<chain_len;i++) gnutls_x509_crt_deinit(chain[i]);
            gnutls_free(chain);
        }
    }

cleanup:
    gnutls_pkcs12_deinit(p12);
    gnutls_global_deinit();
    return 0;
}
EOF
# Check if we have gnutls headers
find / -name "gnutls.h" -o -name "pkcs12.h" 2>/dev/null | head -5

